  [17629] = { "$D1の間、すべての系統の魔法への耐性を$N1上昇させます。一度に効果を得られるフラスコは1つだけです。この効果は死亡しても持続し、他のすべての耐性呪文やアイテムと重複します。", "すべての魔法系統に対する耐性が$N1上昇しています。", 0x0e8310bd, 0x1e7a7a6f, "uu" },
