  [17633] = { "$D1の間、味方の詠唱速度を$N1%上げます。", "詠唱速度が$N1%上昇しています。", 0x6b4d8c25, 0xb128184e, "uu" },
  [17634] = { "あなたは6000合計ダメージまで吸収し、石になっていますが、移動、攻撃、または呪文を唱えることができません。 30秒持続します。", nil, 0x874bb1bf, nil, "um" },
  [17635] = { "1時間400プレーヤー 'sの最大の健康を向上させます。バトルとガーディアンエリキシル剤の両方としてカウントされます。この効果は、死を通して持続します。", nil, 0xd3016201, nil, "um" },
